/**
 * @file chat_tools.cpp
 * @brief Let the model call a local function and send the result back.
 * @note Reads OPENAI_API_KEY and, if set, OPENAI_BASE_URL. Usage: chat_tools [model]
 */
import std;
import moai;

namespace {

    /**
     * @brief Local implementation of the tool offered to the model.
     * @param arguments JSON arguments generated by the model.
     * @return JSON result text.
     */
    auto get_weather(std::string const& arguments) -> std::string {
        auto const input = moai::Json::parse(arguments, nullptr, false);
        auto const city{ input.is_object() ? input.value("city", std::string{ "unknown" }) : std::string{ "unknown" } };
        moai::Json const result = { { "city", city }, { "forecast", "sunny" }, { "celsius", 23 } };
        return result.dump();
    }

} // namespace

/**
 * @brief Run the example.
 * @return Zero on success.
 */
auto main(int argc, char** argv) -> int {
    std::string const model{ argc > 1 ? argv[1] : "gpt-5-mini" };
    auto client{ moai::Client::Create() };
    if (!client) {
        std::println(std::cerr, "{}", client.error());
        return 1;
    }
    moai::ChatCompletionCreateParams params{
        .model = model,
        .messages = { moai::user_message("What is the weather in Hangzhou?") },
        .tools = { moai::ChatCompletionFunctionTool{ .function = {
                       .name = "get_weather",
                       .description = "Get the current weather for a city.",
                       .parameters = moai::Json::parse(R"({
                           "type": "object",
                           "properties": {"city": {"type": "string"}},
                           "required": ["city"],
                           "additionalProperties": false
                       })"),
                       .strict = true,
                   } } },
    };

    for (int round{}; round < 3; ++round) {
        auto const completion{ client->chat.completions.Create(params) };
        if (!completion) {
            std::println(std::cerr, "{}", completion.error());
            return 1;
        }
        auto const& message{ completion->choices.at(0).message };
        if (message.tool_calls.empty()) {
            std::println("{}", message.content.value_or(""));
            return 0;
        }
        params.messages.push_back(moai::assistant_message(message));
        for (auto const& call : message.tool_calls) {
            if (auto const* function{ std::get_if<moai::ChatCompletionMessageFunctionToolCall>(&call) }) {
                std::println("calling {}({})", function->function.name, function->function.arguments);
                params.messages.push_back(moai::tool_message(function->id, get_weather(function->function.arguments)));
            }
        }
    }
    std::println(std::cerr, "the model kept calling tools");
    return 1;
}
